SELECT 'batch_028_690057c2_wav_01' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-d3e438fe-c79') AND album_id='al-d1eb61467eb114e11bfea9d9690057c2') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-d3e438fe-c79') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-d1eb61467eb114e11bfea9d9690057c2' AND name='衔风与愿') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-d1eb61467eb114e11bfea9d9690057c2') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-d1eb61467eb114e11bfea9d9690057c2') AS calculated_size;
